import {PGlite} from '@electric-sql/pglite';
import {readFileSync,readdirSync,writeFileSync} from 'node:fs';
import {randomUUID} from 'node:crypto';
import assert from 'node:assert/strict';
const db=new PGlite(), here=new URL('./',import.meta.url),results=[];
await db.exec(readFileSync(new URL('fixture.sql',here),'utf8'));
await db.exec(readFileSync(new URL('../supabase/migrations/'+readdirSync(new URL('../supabase/migrations',here))[0],here),'utf8'));
const query=(s,p=[])=>db.query(s,p),scalar=async(s,p=[])=>(await query(s,p)).rows[0]?.v;
const check=async(name,fn)=>{await fn();results.push(name);console.log('PASS '+name)};
async function account(verified=true,anonymous=false){const id=randomUUID();await query('insert into auth.users(id,email,email_confirmed_at,is_anonymous) values($1,$2,$3,$4)',[id,id+'@example.test',verified?new Date():null,anonymous]);return id}
async function claims(id){await query("select set_config('request.jwt.claims',$1,false)",[JSON.stringify({sub:id})])}
async function create(id,hc=11.2,request=randomUUID(),name='Synthetic Golfers'){await claims(id);await db.exec('set role authenticated');try{return await scalar('select public.iig_create_owned_playing_group($1,$2,$3,$4) v',[name,'Synthetic Organiser',hc,request])}finally{await db.exec('reset role')}}
async function snapshot(){return scalar(`select jsonb_build_object('groups',(select jsonb_agg(to_jsonb(g) order by id) from public.tens_in_groups g),'owners',(select jsonb_agg(to_jsonb(g) order by group_id) from iig_private.group_owners g),'members',(select jsonb_agg(to_jsonb(g) order by group_id,user_id) from iig_private.group_members g),'settings',(select jsonb_agg(to_jsonb(g) order by group_pin) from public.iig_notification_settings g),'rounds',(select jsonb_agg(to_jsonb(g) order by group_id) from iig_closed_entry.rounds g),'events',(select jsonb_agg(to_jsonb(g) order by id) from public.iig_notification_events g)) v`)}
const id=await account(),request=randomUUID();let created,group;
await check('verified organiser creates group and linked player atomically',async()=>{created=await create(id,11.2,request);group=await scalar('select to_jsonb(g) v from public.tens_in_groups g where id=$1',[created.group_id]);assert.equal(group.state.players.length,1);assert.equal(group.state.players[0].name,'Synthetic Organiser');assert.equal(group.state.players[0].handicap,11.2);assert.equal(group.state.players[0].id,created.player_id);assert.equal(await scalar('select player_id::text v from iig_private.group_members where group_id=$1 and user_id=$2',[created.group_id,id]),created.player_id)});
await check('player is not entered, paid or scored in a competition',async()=>{const p=group.state.players[0];assert.equal(group.state.roundOpen,false);assert.equal(p.playingThisRound,false);assert.equal(p.paid,false);assert.equal(p.stableford,null);assert.equal(p.netScore,null);assert.equal(await scalar('select count(*)::int v from public.iig_notification_events'),0)});
await check('same-request retry returns the same single player',async()=>{const before=await snapshot();assert.deepEqual(await create(id,11.2,request),created);assert.deepEqual(await snapshot(),before)});
await check('existing organiser cannot create another group',async()=>{const before=await snapshot();await assert.rejects(()=>create(id),/already has a group/);assert.deepEqual(await snapshot(),before)});
await check('zero and range-boundary handicaps are supported',async()=>{for(const hc of [0,-10,60]){const c=await create(await account(),hc);assert.equal(await scalar("select (state->'players'->0->>'handicap')::float8 v from public.tens_in_groups where id=$1",[c.group_id]),hc)}});
await check('missing, invalid range and excess precision create no records',async()=>{const other=await account(),before=await snapshot();for(const hc of [null,-10.1,60.1,11.22,'NaN','Infinity'])await assert.rejects(()=>create(other,hc),/Enter your handicap/);assert.deepEqual(await snapshot(),before)});
await check('unverified and anonymous accounts cannot create',async()=>{const before=await snapshot();for(const u of [await account(false),await account(true,true)])await assert.rejects(()=>create(u),/Verified organiser/);assert.deepEqual(await snapshot(),before)});
await check('anonymous database role cannot call the new RPC',async()=>{await db.exec('set role anon');try{await assert.rejects(()=>scalar('select public.iig_create_owned_playing_group($1,$2,$3,$4) v',['No','Nobody',11,randomUUID()]),/permission denied/)}finally{await db.exec('reset role')}});
await check('failed membership write rolls back group and every related record',async()=>{const other=await account(),before=await snapshot();await db.exec("CREATE FUNCTION public.synthetic_fail() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Synthetic join failure'; END $$; CREATE TRIGGER synthetic_fail BEFORE INSERT ON iig_private.group_members FOR EACH ROW EXECUTE FUNCTION public.synthetic_fail();");try{await assert.rejects(()=>create(other),/Synthetic join failure/)}finally{await db.exec('DROP TRIGGER synthetic_fail ON iig_private.group_members; DROP FUNCTION public.synthetic_fail();')}assert.deepEqual(await snapshot(),before)});
await check('failed final confirmation rolls back successful creation and join',async()=>{const original=await scalar("select pg_get_functiondef('public.iig_read_entry_group(text)'::regprocedure) v");const other=await account(),before=await snapshot();await db.exec(original.replace('ELSE\n  result:=',"ELSE\n  RAISE EXCEPTION 'Synthetic final confirmation failure';\n  result:="));try{await assert.rejects(()=>create(other),/Synthetic final confirmation failure/)}finally{await db.exec(original)}assert.deepEqual(await snapshot(),before)});
await check('separate account gets its own player without changing the first group',async()=>{const c=await create(await account());assert.notEqual(c.group_id,created.group_id);assert.notEqual(c.player_id,created.player_id);assert.deepEqual(await scalar('select to_jsonb(g) v from public.tens_in_groups g where id=$1',[created.group_id]),group)});
await check('new function retains caller privileges and fixed search path',async()=>{const p=await scalar("select jsonb_build_object('definer',prosecdef,'settings',proconfig,'anon',has_function_privilege('anon',oid,'EXECUTE'),'authenticated',has_function_privilege('authenticated',oid,'EXECUTE')) v from pg_proc where oid='public.iig_create_owned_playing_group(text,text,numeric,uuid)'::regprocedure");assert.equal(p.definer,false);assert.deepEqual(p.settings,['search_path=pg_catalog']);assert.equal(p.anon,false);assert.equal(p.authenticated,true)});
const receipt={passed:results.length,results,productionDataUsed:false,existingFunctions:'Actual audited LIVE definitions; synthetic local schema and accounts'};
writeFileSync(new URL('database-results.json',here),JSON.stringify(receipt,null,2)+'\n');console.log(JSON.stringify({passed:results.length}));await db.close();
